    const cached = await caches.match(e.request);
    const network = fetch(e.request).then(r => {
      if (r.ok) caches.open(CACHE).then(c => c.put(e.request, r.clone()));
      return r;
    }).catch(() => cached);
    return cached || network;
  })());
});
