// Minimal in-memory IndexedDB, enough for shared/store.js.
const stores = { kv: new Map(), files: new Map(), queue: new Map() }; let seq = 0;
const req = (fn) => { const r = {}; queueMicrotask(() => { r.result = fn(); r.onsuccess?.(); }); return r; };
const tx = (name) => { const t = {}; const m = stores[name]; let n = 0;
  const wrap = fn => { n++; const r = req(fn); const s = r; queueMicrotask(() => queueMicrotask(() => { if (--n === 0) t.oncomplete?.(); })); return s; };
